	struct json_token token;
	int ret;
	size_t *count_ptr = (size_t *)((uint8_t *)val + descr[0].offset_count);
	size_t current_count = 0;

	json_parser_init(&parser, json_string, len);

	ret = json_next_token(&parser, &token);
	if (ret < 0) {
		return ret;
	}

	if (token.type != JSON_TOK_ARRAY_START) {
		return -EINVAL;
	}

	while (json_next_token(&parser, &token) == 0) {
		if (token.type == JSON_TOK_ARRAY_END) {
			break;
		}

