			continue;
		}

		ret = json_token_to_value(&descr[current_count].obj_descr, &token,
					  (uint8_t *)val + descr[current_count].offset);
		if (ret < 0) {
			/*
			 * If the field is polymorphic, try the next descriptor
			 * with the same name.
			 */
			if (descr[current_count].obj_descr.polymorphic) {
				int next_i = current_count + 1;

				while (next_i < descr_len &&
				       json_field_name_match(&token,
