					if (ret == 0) {
						break;
					}
					next_i++;
				}
				if (ret < 0) {
					return ret;
				}
				current_count = next_i;
			} else {
				return ret;
			}
		}

		current_count++;
	}

	*count_ptr = current_count;

	return 0;
